   190	static uint16_t sf32lb52_bt_get_le16(const uint8_t *data)
   191	{
   192	  return (uint16_t)data[0] | ((uint16_t)data[1] << 8);
   193	}
   194	
   195	static void sf32lb52_bt_put_le16(uint8_t *data, uint16_t value)
   196	{
   197	  data[0] = value & 0xff;
   198	  data[1] = value >> 8;
   199	}
   200	
   201	static ssize_t sf32lb52_bt_h4_packet_len(const uint8_t *data, size_t len)
   202	{
   203	  uint16_t payload_len;
   204	
   205	  if (len < H4_HEADER_SIZE)
   206	    {
   207	      return 0;
   208	    }
   209	
   210	  switch (data[0])
   211	    {
   212	      case H4_EVT:
   213	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s))
   214	          {
   215	            return 0;
   216	          }
   217	
   218	        payload_len = data[H4_HEADER_SIZE + 1];
   219	        return H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + payload_len;
   220	
   221	      case H4_ACL:
   222	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s))
   223	          {
   224	            return 0;
   225	          }
   226	
   227	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]);
   228	        return H4_HEADER_SIZE + sizeof(struct bt_hci_acl_hdr_s) + payload_len;
   229	
   230	      case H4_ISO:
   231	        if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s))
   232	          {
   233	            return 0;
   234	          }
   235	
   236	        payload_len = sf32lb52_bt_get_le16(&data[H4_HEADER_SIZE + 2]) & 0x3fff;
   237	        return H4_HEADER_SIZE + sizeof(struct bt_hci_iso_hdr_s) + payload_len;
   238	
   239	      default:
   240	        return -EINVAL;
   241	    }
   242	}
