   244	static void sf32lb52_bt_normalize_event(uint8_t *data, size_t len)
   245	{
   246	  uint16_t opcode;
   247	
   248	  if (len < H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 4 ||
   249	      data[0] != H4_EVT)
   250	    {
   251	      return;
   252	    }
   253	
   254	  if (data[1] == BT_HCI_EVT_CMD_COMPLETE && data[2] >= 4)
   255	    {
   256	      opcode = sf32lb52_bt_get_le16(&data[4]);
   257	      if (opcode == BT_HCI_OP_RESET && data[6] != SF32LB52_HCI_STATUS_SUCCESS)
   258	        {
   259	          data[6] = SF32LB52_HCI_STATUS_SUCCESS;
   260	        }
   261	    }
   262	  else if (data[1] == BT_HCI_EVT_CMD_STATUS && data[2] >= 4)
   263	    {
   264	      opcode = sf32lb52_bt_get_le16(&data[5]);
   265	      if (opcode == BT_HCI_OP_RESET && data[3] != SF32LB52_HCI_STATUS_SUCCESS)
   266	        {
   267	          data[3] = SF32LB52_HCI_STATUS_SUCCESS;
   268	        }
   269	    }
   270	}
   271	
   272	static int sf32lb52_bt_forward_packet(struct sf32lb52_bt_priv_s *priv,
   273	                                      uint8_t *data, size_t len)
   274	{
   275	  enum bt_buf_type_e type;
   276	  int ret;
   277	
   278	  if (len <= H4_HEADER_SIZE)
   279	    {
   280	      return -EINVAL;
   281	    }
   282	
   283	  switch (data[0])
   284	    {
   285	      case H4_EVT:
   286	        sf32lb52_bt_normalize_event(data, len);
   287	        type = BT_EVT;
   288	        break;
   289	
   290	      case H4_ACL:
   291	        type = BT_ACL_IN;
   292	        break;
   293	
   294	      case H4_ISO:
   295	        type = BT_ISO_IN;
   296	        break;
   297	
   298	      default:
   299	        return -EINVAL;
   300	    }
   301	
   302	  ret = bt_netdev_receive(&priv->drv,
   303	                          type,
   304	                          (void *)&data[H4_HEADER_SIZE],
   305	                          len - H4_HEADER_SIZE);
   306	  if (ret < 0)
   307	    {
   308	      wlerr("Failed to receive HCI packet: %d\n", ret);
   309	    }
   310	
   311	  return ret;
   312	}
