   314	static int sf32lb52_bt_synth_cmd_complete(struct sf32lb52_bt_priv_s *priv,
   315	                                          uint16_t opcode,
   316	                                          const uint8_t *return_params,
   317	                                          size_t return_len)
   318	{
   319	  uint8_t event[H4_HEADER_SIZE + sizeof(struct bt_hci_evt_hdr_s) + 3 +
   320	                SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN];
   321	  size_t payload_len;
   322	
   323	  if (return_len > SF32LB52_HCI_MAX_CMD_COMPLETE_RPLEN)
   324	    {
   325	      return -E2BIG;
   326	    }
   327	
   328	  payload_len = 3 + return_len;
   329	  event[0] = H4_EVT;
   330	  event[1] = BT_HCI_EVT_CMD_COMPLETE;
   331	  event[2] = payload_len;
   332	  event[3] = 1;
   333	  sf32lb52_bt_put_le16(&event[4], opcode);
   334	  if (return_len > 0)
   335	    {
   336	      memcpy(&event[6], return_params, return_len);
   337	    }
   338	
   339	  return sf32lb52_bt_forward_packet(priv, event,
   340	                                    H4_HEADER_SIZE +
   341	                                    sizeof(struct bt_hci_evt_hdr_s) +
   342	                                    payload_len);
   343	}
