   890	int sf32lb52_host_send_packet(const uint8_t *data, uint16_t len)
   891	{
   892	  struct circular_buf *tx_ring =
   893	      (struct circular_buf *)SF32LB52_BT_TX_BUF_ADDR;
   894	  uint32_t start_time;
   895	  uint32_t tick_count;
   896	  size_t written;
   897	  size_t remaining;
   898	  size_t offset;
   899	  size_t chunk;
   900	  size_t chunks;
   901	  uint32_t wr_ptr;
   902	  int ret;
   903	
   904	  if (data == NULL || len == 0)
   905	    {
   906	      return -EINVAL;
   907	    }
   908	
   909	  if (g_sf32lb52_bt_status != SF32LB52_BT_STATUS_ENABLED ||
   910	      !g_sf32lb52_bt_env.queue_open)
   911	    {
   912	      syslog(LOG_ERR, "sf32lb52 bt send: controller not ready "
   913	             "(status=%d queue_open=%d)\n",
   914	             g_sf32lb52_bt_status, g_sf32lb52_bt_env.queue_open);
   915	      return -ENODEV;
   916	    }
   917	
   918	  offset = 0;
   919	  remaining = len;
   920	  start_time = HAL_GetTick();
   921	  tick_count = 0;
   922	  chunks = 0;
   923	  wr_ptr = 0;
   924	
   925	  ret = sf32lb52_bt_wait_tx_idle(tx_ring);
   926	  if (ret < 0)
   927	    {
   928	      return ret;
   929	    }
   930	
   931	  while (remaining > 0)
   932	    {
   933	      irqstate_t flags;
   934	
   935	      chunk = sf32lb52_bt_tx_chunk_len(data, len, offset);
   936	
   937	      up_invalidate_dcache((uintptr_t)SF32LB52_BT_TX_BUF_ADDR,
   938	                           (uintptr_t)SF32LB52_BT_TX_BUF_ADDR +
   939	                           sizeof(*tx_ring));
   940	
   941	      flags = enter_critical_section();
   942	      written = sf32lb52_bt_ring_write(tx_ring, data + offset, chunk);
   943	      leave_critical_section(flags);
   944	
   945	      if (written == 0)
   946	        {
   947	          if (HAL_GetTick() != start_time)
   948	            {
   949	              tick_count++;
   950	              start_time = HAL_GetTick();
   951	            }
   952	
   953	          if (tick_count >= 10)
   954	            {
   955	              syslog(LOG_ERR,
   956	                     "sf32lb52 bt tx timeout: remaining=%lu\n",
   957	                     (unsigned long)remaining);
   958	              return -ETIMEDOUT;
   959	            }
   960	
   961	          continue;
   962	        }
   963	
   964	      offset += written;
   965	      remaining -= written;
   966	
   967	      __DSB();
   968	      wr_ptr = tx_ring->write_idx_mirror;
   969	      sf32lb52_bt_trigger_tx();
   970	      chunks++;
   971	    }
   972	
   973	#if SF32LB52_BT_TRACE
   974	  syslog(LOG_INFO,
   975	         "sf32lb52 bt tx publish: total=%u chunks=%lu wr=%08lx first=%02x\n",
   976	         len,
   977	         (unsigned long)chunks,
   978	         (unsigned long)wr_ptr,
   979	         data[0]);
   980	
   981	  sf32lb52_bt_log_tx_state(tx_ring, "queued", wr_ptr);
   982	#endif
   983	
   984	  if (data[0] == SF32LB52_BT_H4_CMD)
   985	    {
   986	      ret = sf32lb52_bt_wait_tx_idle(tx_ring);
   987	      if (ret < 0)
   988	        {
   989	          return ret;
   990	        }
   991	    }
   992	
   993	  return OK;
   994	}

