   708	static void sf32lb52_bt_close(struct bt_driver_s *drv)
   709	{
   710	  int ret;
   711	
   712	  (void)drv;
   713	
   714	  g_sf32lb52_bt_priv.rxlen = 0;
   715	
   716	  /* Full deinit (not just disable) so that the next open re-initialises
   717	   * the IPC queue from a clean state.  Without deinit, controller_init
   718	   * is skipped on re-open (status != IDLE), and LCPU's ring-buffer
   719	   * read pointer (reset on power-on) diverges from HCPU's stale write
   720	   * pointer, causing all HCI commands to be silently dropped. */
   721	  ret = sf32lb52_bt_controller_deinit();
   722	  if (ret < 0)
   723	    {
   724	      wlerr("Failed to deinit HCI controller: %d\n", ret);
   725	    }
   726	}
