   448		if (!buf) {
   449			buf = bt_hci_cmd_create(opcode, 0);
   450			if (!buf) {
   451				return -ENOBUFS;
   452			}
   453		} else {
   454			/* `cmd(buf)` depends on this  */
   455			if (net_buf_pool_get(buf->pool_id) != &hci_cmd_pool) {
   456				__ASSERT_NO_MSG(false);
