   458			}
   459		}
   460	
   461		LOG_DBG("buf %p opcode 0x%04x %s len %u", buf, opcode, bt_hci_opcode_to_str(opcode), buf->len);
   462	
   463		/* This local sem is just for suspending the current thread until the
   464		 * command is processed by the LL. It is given (and we are awaken) by
   465		 * the cmd_complete/status handlers.
   466		 */
   467		k_sem_init(&hdev->sync_sem, 0, 1);
   468		cmd(buf)->sync = &hdev->sync_sem;
