   473		/* TODO: disallow sending sync commands from syswq altogether */
   474	
   475		/* Since the commands are now processed in the syswq, we cannot suspend
   476		 * and wait. We have to send the command from the current context.
   477		 */
   478		if (k_current_get() == &k_sys_work_q.thread) {
   479			/* drain the command queue until we get to send the command of interest. */
   480			struct net_buf *cmd = NULL;
   481	
   482			do {
   483				cmd = k_fifo_peek_head(&hdev->cmd_tx_queue);
   484				LOG_DBG("process cmd %p want %p", cmd, buf);
   485	
   486				/* Wait for a response from the Bluetooth Controller.
   487				 * The Controller may fail to respond if:
   488				 *  - It was never programmed or connected.
   489				 *  - There was a fatal error.
   490				 *
   491				 * See the `BT_HCI_OP_` macros in hci_types.h or
   492				 * Core_v5.4, Vol 4, Part E, Section 5.4.1 and Section 7
   493				 * to map the opcode to the HCI command documentation.
   494				 * Example: 0x0c03 represents HCI_Reset command.
   495				 */
   496				bool success = process_pending_cmd(hdev, HCI_CMD_TIMEOUT);
   497	
   498				if (!success) {
   499					/* Controller unresponsive (e.g. after an HCI
   500					 * Hardware Error). Degrade gracefully instead
   501					 * of crashing the whole system: report the
   502					 * timeout to the caller. The command buffer
   503					 * stays referenced by the tx pipeline; a late
   504					 * completion gives hdev->sync_sem, which is
   505					 * re-initialised by the next call.
   506					 */
   507	
   508					LOG_WRN("command opcode 0x%04x %s timeout",
   509						opcode, bt_hci_opcode_to_str(opcode));
   510					net_buf_unref(buf);
   511					return -ETIMEDOUT;
   512				}
   513			} while (buf != cmd);
   514		}
   515	
   516		/* Now that we have sent the command, suspend until the LL replies.
   517		 * On a timeout the controller is unresponsive (e.g. after an HCI
   518		 * Hardware Error): report -ETIMEDOUT instead of crashing. A late
   519		 * completion gives hdev->sync_sem, which stays valid and is
   520		 * re-initialised by the next synchronous command.
   521		 */
   522		err = k_sem_take(&hdev->sync_sem, HCI_CMD_TIMEOUT);
   523		if (err != 0) {
   524			LOG_WRN("Controller unresponsive, command opcode 0x%04x %s timeout with err %d",
   525				opcode, bt_hci_opcode_to_str(opcode), err);
