   527			return -ETIMEDOUT;
   528		}
   529	
   530		status = cmd(buf)->status;
   531		if (status) {
   532			LOG_WRN("opcode 0x%04x %s status 0x%02x %s", opcode, bt_hci_opcode_to_str(opcode),
   533				status, bt_hci_err_to_str(status));
