   536			switch (status) {
   537			case BT_HCI_ERR_CONN_LIMIT_EXCEEDED:
   538				return -ECONNREFUSED;
   539			case BT_HCI_ERR_INSUFFICIENT_RESOURCES:
   540				return -ENOMEM;
  2450			conn->rv.manufacturer = sys_le16_to_cpu(evt->manufacturer);
