  2584			bt_hci_opcode_to_str(opcode),
  2585			status, bt_hci_err_to_str(status), evt_buf);
  2586	
  2587		/* Unsolicited cmd complete. This does not complete a command.
  2588		 * The controller can send these for effect of the `ncmd` field.
  2589		 */
  2590		if (opcode == 0) {
  2591			goto exit;
  2592		}
  2593	
  2594		/* Take the original command buffer reference. */
  2595		buf = (struct net_buf *)atomic_ptr_clear((atomic_ptr_t *)&hdev->sent_cmd);
  2596	
  2597		if (!buf) {
  2598			LOG_ERR("No command sent for cmd complete 0x%04x", opcode);
  2599			goto exit;
  2600		}
  2601	
  2602		if (cmd(buf)->opcode != opcode) {
  2603			LOG_ERR("OpCode 0x%04x %s completed instead of expected 0x%04x %s", opcode,
  2604				bt_hci_opcode_to_str(opcode), cmd(buf)->opcode, bt_hci_opcode_to_str(cmd(buf)->opcode));
  2605			buf = atomic_ptr_set((atomic_ptr_t *)&hdev->sent_cmd, buf);
