  2608		}
  2609	
  2610		/* Response data is to be delivered in the original command
  2611		 * buffer.
  2612		 */
  2613		if (evt_buf != buf) {
  2614			net_buf_reset(buf);
  2615			bt_buf_set_type(buf, BT_BUF_EVT);
  2616			net_buf_reserve(buf, BT_BUF_RESERVE);
  2617			net_buf_add_mem(buf, evt_buf->data, evt_buf->len);
  2618		}
  2619	
  2620		if (cmd(buf)->state && !status) {
  2621			struct bt_hci_cmd_state_set *update = cmd(buf)->state;
  2622	
  2623			atomic_set_bit_to(update->target, update->bit, update->val);
