   245	static int32_t ipc_queue_do_close(ipc_queue_handle_t handle,
   246	                                  int32_t (*disable_interrupt)(
   247	                                      ipc_hw_q_handle_t *hw_q_handle))
   248	{
   249	    int32_t offset;
   250	    ipc_queue_t *queue;
   251	    uint32_t mask;
   252	    int32_t result;
   253	
   254	    if (!is_valid_handle(handle))
   255	    {
   256	        return -1;
   257	    }
   258	
   259	    offset = IPC_QUEUE_HANDLE_2_OFFSET(handle);
   260	    queue = &ipc_ctx.queues[offset];
   261	    if (!queue->active)
   262	    {
   263	        return -1;
   264	    }
   265	
   266	    mask = os_interrupt_disable();
   267	    result = disable_interrupt(&queue->hw_q_handle);
   268	    queue->active = false;
   269	    queue->rx_ring_buffer = NULL;
   270	    queue->tx_ring_buffer = NULL;
   271	    os_interrupt_enable(mask);
   272	
   273	    return result;
   274	}
