    65	__ROM_USED size_t circular_buf_put(struct circular_buf *cb, const uint8_t *ptr,
    66	                                   uint16_t length)
    67	{
    68	    uint16_t size;
    69	    uint32_t wr_mirror;
    70	    uint32_t wr_idx;
    71	
    72	    SF_ASSERT(cb != NULL);
    73	
    74	    size = circular_buf_space_len(cb);
    75	    if (size == 0)
    76	    {
    77	        return 0;
    78	    }
    79	
    80	    if (size < length)
    81	    {
    82	        length = size;
    83	    }
    84	
    85	    wr_idx = CB_GET_PTR_IDX(cb->write_idx_mirror);
    86	    wr_mirror = CB_GET_PTR_MIRROR(cb->write_idx_mirror);
    87	    if ((cb->buffer_size - wr_idx) > length)
    88	    {
    89	        memcpy(&cb->wr_buffer_ptr[wr_idx], ptr, length);
    90	        wr_idx += length;
    91	        cb->write_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, wr_mirror);
    92	        return length;
    93	    }
    94	
    95	    memcpy(&cb->wr_buffer_ptr[wr_idx], &ptr[0], cb->buffer_size - wr_idx);
    96	    memcpy(&cb->wr_buffer_ptr[0], &ptr[cb->buffer_size - wr_idx],
    97	           length - (cb->buffer_size - wr_idx));
    98	
    99	    wr_mirror = ~wr_mirror;
   100	    wr_idx = length - (cb->buffer_size - wr_idx);
   101	    cb->write_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(wr_idx, wr_mirror);
   102	
   103	    return length;
   104	}
