   200	__ROM_USED size_t circular_buf_get_and_update_len(struct circular_buf *cb,
   201	                                                  uint8_t *ptr,
   202	                                                  uint16_t length,
   203	                                                  size_t *remaining_len)
   204	{
   205	    size_t size;
   206	    uint32_t mask;
   207	    uint32_t rd_mirror;
   208	    uint32_t rd_idx;
   209	
   210	    SF_ASSERT(cb != NULL);
   211	
   212	    size = circular_buf_data_len(cb);
   213	    if (size == 0)
   214	    {
   215	        return 0;
   216	    }
   217	
   218	    if (size < length)
   219	    {
   220	        length = size;
   221	    }
   222	
   223	    rd_idx = CB_GET_PTR_IDX(cb->read_idx_mirror);
   224	    rd_mirror = CB_GET_PTR_MIRROR(cb->read_idx_mirror);
   225	    if (cb->buffer_size - rd_idx > length)
   226	    {
   227	        memcpy(ptr, &cb->rd_buffer_ptr[rd_idx], length);
   228	
   229	        mask = os_interrupt_disable();
   230	        if (remaining_len)
   231	        {
   232	            *remaining_len = circular_buf_data_len(cb) - length;
   233	        }
   234	        rd_idx += length;
   235	        cb->read_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(rd_idx, rd_mirror);
   236	        os_interrupt_enable(mask);
   237	
   238	        return length;
   239	    }
   240	
   241	    memcpy(&ptr[0], &cb->rd_buffer_ptr[rd_idx], cb->buffer_size - rd_idx);
   242	    memcpy(&ptr[cb->buffer_size - rd_idx], &cb->rd_buffer_ptr[0],
   243	           length - (cb->buffer_size - rd_idx));
   244	
   245	    mask = os_interrupt_disable();
   246	    if (remaining_len)
   247	    {
   248	        *remaining_len = circular_buf_data_len(cb) - length;
   249	    }
   250	    rd_mirror = ~rd_mirror;
   251	    rd_idx = length - (cb->buffer_size - rd_idx);
   252	    cb->read_idx_mirror = CB_MAKE_PTR_IDX_MIRROR(rd_idx, rd_mirror);
   253	    os_interrupt_enable(mask);
   254	
