    42	
    43	/* SRAM memory configuration for SF32LB52 */
    44	
    45	#define SRAM_START  0x20000000
    46	#define SRAM_SIZE   0x00080000    /* 512 KB */
    47	
    48	/* The top of HCPU SRAM is reserved by the vendor memory map (mem_map.h)
    49	 * and must never be handed to the heap:
    50	 *   0x2007FB00-0x2007FBFF  HCPU_CUSTOM_CONFIG (256B, consumed by the
    51	 *                          closed LCPU/ROM side)
    52	 *   0x2007FC00-0x2007FFFF  HPSYS_MBOX_BUF (2 x 512B); channel 1 carries
    53	 *                          the BT HCI stream at fixed addresses that the
    54	 *                          LCPU reads from its own RAM space.
    55	 * Heap allocations reaching this window corrupt the BT stream and the
    56	 * controller dies with "Hardware error, code 0" on the next connection.
    57	 */
    58	
    59	#define HCPU_TOP_RESERVED   0x500
    60	#define SRAM_END    (SRAM_START + SRAM_SIZE - HCPU_TOP_RESERVED)
    61	
    62	/* PSRAM memory configuration for SF32LB52 (MPI1 SBUS) */
    63	
    64	#define PSRAM_START 0x60000000
    65	#define PSRAM_SIZE  0x00800000    /* 8 MB */
