    75	#ifdef CONFIG_BSP_USING_PSRAM
    76	static bool g_psram_ready;
    77	
    78	static void sifli_psram_preinit(void)
    79	{
    80	  qspi_configure_t qspi_cfg =
    81	  {
    82	    .Instance = hwp_qspi1,
    83	    .SpiMode  = CONFIG_BSP_QSPI1_MODE,
    84	    .msize    = CONFIG_BSP_QSPI1_MEM_SIZE,
    85	    .base     = QSPI1_MEM_BASE,
    86	  };
    87	  static FLASH_HandleTypeDef psram_handle;
    88	
    89	  /* Enable 1.8V LDO required by PSRAM. */
    90	
    91	  HAL_PMU_ConfigPeriLdo(PMU_PERI_LDO_1V8, true, true);
    92	
    93	  /* Use SYSCLK for early boot safety. DLL2 path is enabled later by HAL. */
    94	
    95	  HAL_RCC_HCPU_ClockSelect(RCC_CLK_MOD_FLASH1, RCC_CLK_FLASH_SYSCLK);
    96	
    97	  /* Use configured PSRAM mode directly to avoid early-boot PID dependency. */
    98	
    99	  if (qspi_cfg.SpiMode == SPI_MODE_NOR)
   100	    {
   101	      g_psram_ready = false;
   102	      return;
   103	    }
   104	
   105	  /* Avoid early power-mode query here; HAL_Init will handle PM state later. */
   106	
   107	  psram_handle.wakeup = 0;
   108	
   109	  /* Keep divider aligned with existing board implementation. */
   110	
   111	  g_psram_ready = (HAL_MPI_PSRAM_Init(&psram_handle, &qspi_cfg, 2) == HAL_OK);
   112	}
   113	#endif
