   135	/****************************************************************************
   136	 * Name: up_allocate_heap/up_allocate_kheap
   137	 *
   138	 * Description:
   139	 *   This function will be called to dynamically set aside the heap region.
   140	 *
   141	 *   - For the normal "flat" build, this function returns the size of the
   142	 *     single heap.
   143	 *   - For the protected build (CONFIG_BUILD_PROTECTED=y) with both kernel-
   144	 *     and user-space heaps (CONFIG_MM_KERNEL_HEAP=y), this function
   145	 *     provides the size of the unprotected, user-space heap.
   146	 *   - For the kernel build (CONFIG_BUILD_KERNEL=y), this function provides
   147	 *     the size of the protected, kernel-space heap.
   148	 *
   149	 *   If a protected kernel-space heap is provided, the kernel heap must be
   150	 *   allocated by an analogous up_allocate_kheap(). A custom version of this
   151	 *   file is needed if memory protection of the kernel heap is required.
   152	 *
   153	 *   The following memory map is assumed for the flat build:
   154	 *
   155	 *     .data region.  Size determined at link time.
   156	 *     .bss  region  Size determined at link time.
   157	 *     IDLE thread stack.  Size determined by CONFIG_IDLETHREAD_STACKSIZE.
   158	 *     Heap.  Extends to the end of SRAM.
   159	 *
   160	 *   The following memory map is assumed for the kernel build:
   161	 *
   162	 *     Kernel .data region.  Size determined at link time.
   163	 *     Kernel .bss  region  Size determined at link time.
   164	 *     Kernel IDLE thread stack.  Size determined by
   165	 *       CONFIG_IDLETHREAD_STACKSIZE.
   166	 *     Padding for alignment
   167	 *     User .data region.  Size determined at link time.
   168	 *     User .bss region  Size determined at link time.
   169	 *     Kernel heap.  Size determined by CONFIG_MM_KERNEL_HEAPSIZE.
   170	 *     User heap.  Extends to the end of SRAM.
   171	 *
   172	 ****************************************************************************/
   173	
   174	void up_allocate_heap(FAR void **heap_start, size_t *heap_size)
   175	{
   176	  /* The heap starts at g_idle_topstack and extends to the end of SRAM */
   177	  
   178	  *heap_start = (FAR void *)g_idle_topstack;
   179	  *heap_size  = SRAM_END - g_idle_topstack;
   180	}
