   149	__HAL_ROM_USED HAL_StatusTypeDef HAL_HPAON_WakeCore(uint8_t core_id)
   150	{
   151	    HAL_StatusTypeDef ret = HAL_OK;
   152	    if (core_id == CORE_ID_LCPU)
   153	    {
   154	#ifdef SF32LB52X
   155	        uint32_t mask;
   156	#endif /* SF32LB52X */
   157	        /* Bounded LP_ACTIVE polling: original code spun forever waiting for
   158	         * LCPU to ACK; on single-core boards (no LCPU image, e.g. LCKFB
   159	         * Huangshan / sf32lb52_lchspi_ulp) LP_ACTIVE never asserts and HCPU
   160	         * locks up. Cap each wait at ~50 ms (50000 us) and return HAL_ERROR
   161	         * so callers can fall back gracefully.
   162	         */
   163	
   164	        uint32_t guard;
   165	
   166	        hwp_hpsys_aon->ISSR |= HPSYS_AON_ISSR_HP2LP_REQ;
