   171	        {
   172	            if (guard-- == 0)
   173	            {
   174	                return HAL_ERROR;
   175	            }
   176	
   177	            HAL_Delay_us(1);
   178	        }
   179	
   180	        HAL_Delay_us(30);
   181	
   182	        guard = 50000;
