   193	/* Build the 6-byte Status value: version(1) conn_state(1) last_sync(4, LE) */
   194	
   195	static ssize_t bridge_read_status(struct bt_conn *conn,
   196	                                  const struct bt_gatt_attr *attr,
   197	                                  void *buf, uint16_t len, uint16_t offset)
   198	{
   199	  uint8_t value[6];
   200	  uint32_t sync = g_bridge.last_sync_utc;
   201	  uint8_t conn_state = (g_bridge.state == AI_WATCH_BLE_BSP_CONNECTED) ?
   202	                        1 : 0;
   203	
   204	  value[0] = BRIDGE_PROTOCOL_VERSION;
   205	  value[1] = conn_state;
   206	  value[2] = (uint8_t)(sync >> 0);
   207	  value[3] = (uint8_t)(sync >> 8);
   208	  value[4] = (uint8_t)(sync >> 16);
   209	  value[5] = (uint8_t)(sync >> 24);
   210	
   211	  return bt_gatt_attr_read(conn, attr, buf, len, offset,
   212	                           value, sizeof(value));
   213	}
