   215	/* TimeSync write: version(1) utc(4, LE) tz(2, LE signed). Strictly
   216	 * validated here on the BT thread; the payload is handed to the app
   217	 * which performs clock_settime on its own thread.
   218	 */
   219	
   220	static ssize_t bridge_write_timesync(struct bt_conn *conn,
   221	                                     const struct bt_gatt_attr *attr,
   222	                                     const void *buf, uint16_t len,
   223	                                     uint16_t offset, uint8_t flags)
   224	{
   225	  const uint8_t *data = buf;
   226	  struct ai_watch_ble_bsp_timesync_s sync;
   227	  uint32_t utc;
   228	  uint16_t tzs;
   229	
   230	  if (offset != 0)
   231	    {
   232	      return BT_GATT_ERR(BT_ATT_ERR_INVALID_OFFSET);
   233	    }
   234	
   235	  if (len != AI_WATCH_BLE_TIMESYNC_SIZE)
   236	    {
   237	      BRIDGE_LOG("timesync rejected: len %u\n", len);
   238	      return BT_GATT_ERR(BT_ATT_ERR_INVALID_ATTRIBUTE_LEN);
   239	    }
   240	
   241	  if (data[0] != BRIDGE_PROTOCOL_VERSION)
   242	    {
   243	      BRIDGE_LOG("timesync rejected: version %u\n", data[0]);
   244	      return BT_GATT_ERR(BT_ATT_ERR_VALUE_NOT_ALLOWED);
   245	    }
   246	
   247	  memcpy(&utc, &data[1], sizeof(utc));
   248	  memcpy(&tzs, &data[5], sizeof(tzs));
   249	
   250	  if (utc < BRIDGE_TS_MIN_UTC || utc > BRIDGE_TS_MAX_UTC)
   251	    {
   252	      BRIDGE_LOG("timesync rejected: utc %lu out of range\n",
   253	                 (unsigned long)utc);
   254	      return BT_GATT_ERR(BT_ATT_ERR_VALUE_NOT_ALLOWED);
   255	    }
   256	
   257	  if ((int16_t)tzs < BRIDGE_TS_MIN_TZ || (int16_t)tzs > BRIDGE_TS_MAX_TZ)
   258	    {
   259	      BRIDGE_LOG("timesync rejected: tz %d out of range\n", (int16_t)tzs);
   260	      return BT_GATT_ERR(BT_ATT_ERR_VALUE_NOT_ALLOWED);
   261	    }
