   632	 * (patch install + RF calibration + ring sync).  After this the
   633	 * controller answers HCI again and the zblue host can tear itself
   634	 * down cleanly.  Must run from a context where blocking is OK.
   635	 */
   636	int sf32lb52_bth4_controller_restart(void)
   637	{
   638	  int ret;
   639	
   640	  ret = sf32lb52_bt_controller_deinit();
   641	  if (ret < 0 && ret != -EPERM)
   642	    {
   643	      syslog(LOG_ERR, "sf32lb52 bth4 restart: deinit failed: %d\n", ret);
   644	      return ret;
   645	    }
   646	
   647	  ret = sf32lb52_bt_controller_init();
   648	  if (ret < 0)
   649	    {
   650	      syslog(LOG_ERR, "sf32lb52 bth4 restart: init failed: %d\n", ret);
   651	      return ret;
   652	    }
   653	
   654	  ret = sf32lb52_hci_register_callback(sf32lb52_bt_recv_cb);
   655	  if (ret < 0)
   656	    {
   657	      syslog(LOG_ERR, "sf32lb52 bth4 restart: register cb failed: %d\n",
   658	             ret);
   659	      return ret;
   660	    }
   661	
   662	  return sf32lb52_bt_controller_enable();
   663	}
   664	
   665	static int sf32lb52_bt_ensure_controller_enabled(uint16_t opcode)
   666	{
   667	  int ret;
   668	
   669	  ret = sf32lb52_bt_controller_enable();
   670	  if (ret < 0)
   671	    {
   672	      syslog(LOG_ERR,
   673	             "sf32lb52 bth4 controller enable failed before opcode=0x%04x: %d\n",
   674	             opcode,
   675	             ret);
   676	    }
   677	
   678	  return ret;
   679	}
