  HAL_SECU_SetAttr(SECU_MOD_HCPU, SECU_ROLE_MASTER, SECU_FLAG_NONE);
  HAL_SECU_Apply(SECU_GROUP_HPMST);
#endif
  HAL_Delay_us(5000);
  return 0;
}

