 548	static int sf32lb52_bt_send(struct bt_driver_s *drv,
 549	                            enum bt_buf_type_e type,
 550	                            void *data, size_t len)
 551	{
 552	  struct sf32lb52_bt_priv_s *priv = &g_sf32lb52_bt_priv;
 553	  uint8_t *hdr = (uint8_t *)data - drv->head_reserve;
 554	  uint16_t opcode;
 555	  int ret;
 556	
 557	  switch (type)
 558	    {
 559	      case BT_CMD:
 560	        *hdr = H4_CMD;
 561	        break;
 562	      case BT_ACL_OUT:
 563	        *hdr = H4_ACL;
 564	        break;
 565	      case BT_ISO_OUT:
 566	        *hdr = H4_ISO;
 567	        break;
 568	      default:
 569	        syslog(LOG_ERR, "sf32lb52 bth4 send: bad type %u\n",
 570	               (unsigned int)type);
 571	        return -EINVAL;
 572	    }
 573	
 574	  if (type == BT_CMD && len >= sizeof(struct bt_hci_cmd_hdr_s))
 575	    {
 576	      opcode = sf32lb52_bt_get_le16(data);
 577	      if (sf32lb52_bt_emulate_cmd(priv, opcode, &ret))
 578	        {
 579	          if (ret < 0)
 580	            {
 581	              syslog(LOG_ERR, "sf32lb52 bth4 send: emulate 0x%04x "
 582	                     "failed: %d\n", opcode, ret);
 583	              return ret;
 584	            }
 585	
 586	          return len;
 587	        }
 588	
 589	      ret = sf32lb52_bt_ensure_controller_enabled(opcode);
 590	      if (ret < 0)
 591	        {
 592	          return ret;
 593	        }
 594	    }
 595	  else
 596	    {
 597	      ret = sf32lb52_bt_ensure_controller_enabled(0);
 598	      if (ret < 0)
 599	        {
 600	          return ret;
 601	        }
 602	    }
 603	
 604	  priv->drop_rx_until_tx = false;
 605	
 606	  if (SF32LB52_BT_TRACE && type == BT_ACL_OUT)
 607	    {
 608	      syslog(LOG_INFO,
 609	             "sf32lb52 bth4 tx: type=%u len=%lu h4=%02x acl=%02x %02x %02x %02x\n",
 610	             (unsigned int)type,
 611	             (unsigned long)(len + drv->head_reserve),
 612	             hdr[0],
 613	             len >= 1 ? hdr[1] : 0,
 614	             len >= 2 ? hdr[2] : 0,
 615	             len >= 3 ? hdr[3] : 0,
 616	             len >= 4 ? hdr[4] : 0);
 617	    }
 618	
 619	  ret = sf32lb52_host_send_packet(hdr, len + drv->head_reserve);
 620	  if (ret < 0)
 621	    {
 622	      syslog(LOG_ERR, "sf32lb52 bth4 send: host_send_packet failed: %d\n",
 623	             ret);
 624	      return ret;
 625	    }
 626	
 627	  return len;
 628	}
