 659	    }
 660	
 661	  ret = sf32lb52_hci_register_callback(sf32lb52_bt_recv_cb);
 662	  if (ret < 0)
 663	    {
 664	      syslog(LOG_ERR, "sf32lb52 bth4 restart: register cb failed: %d\n",
 665	             ret);
 666	      return ret;
 667	    }
 668	
 669	  return sf32lb52_bt_controller_enable();
