3396	uint8_t bt_gatt_check_perm(struct bt_conn *conn, const struct bt_gatt_attr *attr,
3397				uint16_t mask)
3398	{
3399		if ((mask & BT_GATT_PERM_READ) &&
3400		    (!(attr->perm & BT_GATT_PERM_READ_MASK) || !attr->read)) {
3401			return BT_ATT_ERR_READ_NOT_PERMITTED;
3402		}
3403	
3404		if ((mask & BT_GATT_PERM_WRITE) &&
3405		    (!(attr->perm & BT_GATT_PERM_WRITE_MASK) || !attr->write)) {
3406			return BT_ATT_ERR_WRITE_NOT_PERMITTED;
3407		}
3408	
3409		if (IS_ENABLED(CONFIG_BT_CONN_DISABLE_SECURITY)) {
3410			return 0;
3411		}
3412	
3413		mask &= attr->perm;
3414	
3415		/*
3416		 * Core Specification 5.4 Vol. 3 Part C 10.3.1
3417		 *
3418		 * If neither an LTK nor an STK is available, the service
3419		 * request shall be rejected with the error code
3420		 * “Insufficient Authentication”.
3421		 * Note: When the link is not encrypted, the error code
3422		 * “Insufficient Authentication” does not indicate that
3423		 *  MITM protection is required.
3424		 *
3425		 * If an LTK or an STK is available and encryption is
3426		 * required (LE security mode 1) but encryption is not
3427		 * enabled, the service request shall be rejected with
3428		 * the error code “Insufficient Encryption”.
3429		 */
3430	
3431		if (mask &
3432		    (BT_GATT_PERM_ENCRYPT_MASK | BT_GATT_PERM_AUTHEN_MASK | BT_GATT_PERM_LESC_MASK)) {
3433	#if defined(CONFIG_BT_SMP)
3434			if (!conn->encrypt) {
3435				if (bt_conn_ltk_present(conn)) {
3436					return BT_ATT_ERR_INSUFFICIENT_ENCRYPTION;
3437				} else {
3438					return BT_ATT_ERR_AUTHENTICATION;
3439				}
3440			}
3441	
3442			if (mask & BT_GATT_PERM_AUTHEN_MASK) {
3443				if (bt_conn_get_security(conn) < BT_SECURITY_L3) {
3444					return BT_ATT_ERR_AUTHENTICATION;
3445				}
3446			}
3447	
3448			if (mask & BT_GATT_PERM_LESC_MASK) {
3449				const struct bt_keys *keys = conn->le.keys;
3450	
3451				if (!keys || (keys->flags & BT_KEYS_SC) == 0) {
3452					return BT_ATT_ERR_AUTHENTICATION;
3453				}
3454			}
3455	#else
3456			return BT_ATT_ERR_AUTHENTICATION;
3457	#endif /* CONFIG_BT_SMP */
3458		}
3459	
3460		return 0;
3461	}
