   101	static int h4_send_data(struct h4_data *h4, uint8_t *buf, size_t count)
   102	{
   103		ssize_t ret, nwritten = 0;
   104	
   105		while (nwritten != count) {
   106			ret = file_write(&h4->wfile, buf + nwritten,
   107					 count - nwritten);
   108			if (ret < 0) {
   109				if (ret == -EAGAIN) {
   110					usleep(500);
   111					continue;
   112				} else {
   113					/* LOG_ERR collides with zephyr/log.h in
   114					 * this TU; 3 == LOG_ERR priority.
   115					 * file_write() returns the negated errno
   116					 * directly.
   117					 */
   118	
   119					syslog(3,
   120					       "h4: file_write failed ret=%d "
   121					       "nwritten=%zu count=%zu\n",
   122					       (int)ret, nwritten, count);
   123					return ret;
   124				}
   125			}
   126	
   127			nwritten += ret;
   128		}
   129	
   130		return nwritten;
   131	}
