   133	static struct net_buf *get_rx(const uint8_t *buf)
   134	{
   135		bool discardable = false;
   136		k_timeout_t timeout = K_FOREVER;
   137	
   138		switch (buf[0]) {
   139		case BT_HCI_H4_EVT:
   140			if (buf[1] == BT_HCI_EVT_LE_META_EVENT &&
   141			    (buf[3] == BT_HCI_EVT_LE_ADVERTISING_REPORT)) {
   142				discardable = true;
   143				timeout = K_NO_WAIT;
   144			}
   145	
   146			return bt_buf_get_evt(buf[1], discardable, timeout);
   147		case BT_HCI_H4_ACL:
   148			return bt_buf_get_rx(BT_BUF_ACL_IN, K_FOREVER);
   149		case BT_HCI_H4_ISO:
   150			if (IS_ENABLED(CONFIG_BT_ISO)) {
   151				return bt_buf_get_rx(BT_BUF_ISO_IN, K_FOREVER);
   152			}
   153			__fallthrough;
   154		default:
   155			LOG_ERR("Unknown packet type: %u", buf[0]);
   156		}
   157	
   158		return NULL;
   159	}
