   161	/**
   162	 * @brief Decode the length of an HCI H4 packet and check it's complete
   163	 * @details Decodes packet length according to Bluetooth spec v5.4 Vol 4 Part E
   164	 * @param buf	Pointer to a HCI packet buffer
   165	 * @param buf_len	Bytes available in the buffer
   166	 * @return Length of the complete HCI packet in bytes, -1 if cannot find an HCI
   167	 *         packet, 0 if more data required.
   168	 */
   169	static int32_t hci_packet_complete(const uint8_t *buf, uint16_t buf_len)
   170	{
   171		uint16_t payload_len = 0;
   172		const uint8_t type = buf[0];
   173		uint8_t header_len = sizeof(type);
   174		const uint8_t *hdr = &buf[sizeof(type)];
   175	
   176		switch (type) {
   177		case BT_HCI_H4_CMD: {
   178			if (buf_len < header_len + BT_HCI_CMD_HDR_SIZE) {
   179				return 0;
   180			}
   181			const struct bt_hci_cmd_hdr *cmd = (const struct bt_hci_cmd_hdr *)hdr;
   182	
   183			/* Parameter Total Length */
   184			payload_len = cmd->param_len;
   185			header_len += BT_HCI_CMD_HDR_SIZE;
   186			break;
   187		}
   188		case BT_HCI_H4_ACL: {
   189			if (buf_len < header_len + BT_HCI_ACL_HDR_SIZE) {
   190				return 0;
   191			}
   192			const struct bt_hci_acl_hdr *acl = (const struct bt_hci_acl_hdr *)hdr;
   193	
   194			/* Data Total Length */
   195			payload_len = sys_le16_to_cpu(acl->len);
   196			header_len += BT_HCI_ACL_HDR_SIZE;
   197			break;
   198		}
   199		case BT_HCI_H4_SCO: {
   200			if (buf_len < header_len + BT_HCI_SCO_HDR_SIZE) {
   201				return 0;
   202			}
   203			const struct bt_hci_sco_hdr *sco = (const struct bt_hci_sco_hdr *)hdr;
   204	
   205			/* Data_Total_Length */
   206			payload_len = sco->len;
   207			header_len += BT_HCI_SCO_HDR_SIZE;
   208			break;
   209		}
   210		case BT_HCI_H4_EVT: {
   211			if (buf_len < header_len + BT_HCI_EVT_HDR_SIZE) {
   212				return 0;
   213			}
   214			const struct bt_hci_evt_hdr *evt = (const struct bt_hci_evt_hdr *)hdr;
   215	
   216			/* Parameter Total Length */
   217			payload_len = evt->len;
   218			header_len += BT_HCI_EVT_HDR_SIZE;
   219			break;
   220		}
   221		case BT_HCI_H4_ISO: {
   222			if (buf_len < header_len + BT_HCI_ISO_HDR_SIZE) {
   223				return 0;
   224			}
   225			const struct bt_hci_iso_hdr *iso = (const struct bt_hci_iso_hdr *)hdr;
   226	
   227			/* ISO_Data_Load_Length parameter */
   228			payload_len = bt_iso_hdr_len(sys_le16_to_cpu(iso->len));
   229			header_len += BT_HCI_ISO_HDR_SIZE;
   230			break;
   231		}
   232		/* If no valid packet type found */
   233		default:
   234			LOG_WRN("Unknown packet type 0x%02x", type);
   235			return -1;
   236		}
   237	
   238		/* Request more data */
   239		if (buf_len < header_len + payload_len) {
   240			return 0;
   241		}
   242	
   243		return (int32_t)header_len + payload_len;
   244	}
