   570	
   571	int bt_hci_le_rand_mc(uint8_t dev_id, void *buffer, size_t len)
   572	{
   573		struct bt_hci_rp_le_rand *rp;
   574		struct net_buf *rsp;
   575		size_t count;
   576		int err;
   577		struct bt_dev *hdev;
   578	
   579		hdev = bt_dev_get(dev_id);
   580		if (!hdev) {
   581			return -ENODEV;
   582		}
   583	
   584		/* Check first that HCI_LE_Rand is supported */
   585		if (!BT_CMD_TEST(hdev->supported_commands, 27, 7)) {
   586			return -ENOTSUP;
   587		}
   588	
   589		while (len > 0) {
   590			/* Number of bytes to fill on this iteration */
   591			count = MIN(len, sizeof(rp->rand));
   592			/* Request the next 8 bytes over HCI */
   593			err = bt_hci_cmd_send_sync(hdev, BT_HCI_OP_LE_RAND, NULL, &rsp);
   594			if (err) {
   595				return err;
   596			}
   597			/* Copy random data into buffer */
   598			rp = (void *)rsp->data;
   599			memcpy(buffer, rp->rand, count);
   600	
   601			net_buf_unref(rsp);
   602			buffer = (uint8_t *)buffer + count;
   603			len -= count;
   604		}
   605	
   606		return 0;
   607	}
