  1735	static void sc_indicate(struct bt_dev *hdev, uint16_t start, uint16_t end)
  1736	{
  1737	#if defined(CONFIG_BT_GATT_DYNAMIC_DB) ||                                                          \
  1738		(defined(CONFIG_BT_GATT_CACHING) && defined(CONFIG_BT_SETTINGS))
  1739		LOG_DBG("start 0x%04x end 0x%04x", start, end);
  1740	
  1741		if (!atomic_test_and_set_bit(hdev->gatt_ctx->gatt_sc.flags, SC_RANGE_CHANGED)) {
  1742			hdev->gatt_ctx->gatt_sc.start = start;
  1743			hdev->gatt_ctx->gatt_sc.end = end;
  1744			goto submit;
  1745		}
  1746	
  1747		if (!update_range(&hdev->gatt_ctx->gatt_sc.start, &hdev->gatt_ctx->gatt_sc.end, start, end)) {
  1748			return;
  1749		}
  1750	
  1751	submit:
  1752		if (atomic_test_bit(hdev->gatt_ctx->gatt_sc.flags, SC_INDICATE_PENDING)) {
  1753			LOG_DBG("indicate pending, waiting until complete...");
  1754			return;
  1755		}
  1756	
  1757		/* Reschedule since the range has changed */
  1758		sc_work_submit(hdev, SC_TIMEOUT);
  1759	#endif /* BT_GATT_DYNAMIC_DB || (BT_GATT_CACHING && BT_SETTINGS) */
  1760	}
