5073	/* Return `true` if a command was processed/sent */
5074	static bool process_pending_cmd(struct bt_dev *hdev, k_timeout_t timeout)
5075	{
5076		if (!k_fifo_is_empty(&hdev->cmd_tx_queue)) {
5077			if (k_sem_take(&hdev->ncmd_sem, timeout) == 0) {
5078				hci_core_send_cmd(hdev);
5079				return true;
5080			}
5081		}
5082	
5083		return false;
5084	}
